pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Restrict to admissible domain: _tos must be non-empty to satisfy the require.
        vm.assume(_tos.length > 0);
        // Keep input space wide; no further artificial constraints.

        // Wrap the call to detect revert and capture return value.
        bool ok;
        bool returned;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            ok = true;
            returned = ret;
        } catch {
            ok = false;
        }

        // Invariant: if the call succeeds, it must return true.
        assertTrue(!ok || returned);
    }
}

