// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // Deploy a helper that always reverts on calls to transferFrom
        Reverter reverter = new Reverter();
        // Ensure at least one target is the reverter to trigger the failure
        _tos[0] = address(reverter);
        // Make the call
        vm.prank(from);
        bool ok;
        try c.transfer(from, address(reverter), _tos, v) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        // Reference contract always reverts (ok==false), buggy version succeeds (ok==true)
        // Therefore, correct invariant: ok is always false
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

